<template>
  <section class="history container">
    <h1>Lịch sử đặt hàng</h1><p>Theo dõi đơn hàng, giao nhận và đánh giá sản phẩm đã mua.</p>
    <nav class="order-tabs" aria-label="Lọc lịch sử đơn hàng"><button v-for="tab in tabs" :key="tab.id" :class="{ active: activeTab === tab.id }" @click="activeTab = tab.id">{{ tab.label }} <span v-if="countFor(tab.id)">{{ countFor(tab.id) }}</span></button></nav>
    <div v-if="loading" class="empty">Đang tải đơn hàng...</div><div v-else-if="!filteredOrders.length" class="empty">Chưa có đơn hàng trong mục này.</div>
    <router-link v-else v-for="order in filteredOrders" :key="order.id" :to="`/order/${order.id}`" class="order"><div class="order-main"><b>#{{ order.order_code }}</b><small>{{ date(order.created_at) }} · {{ order.payment_method === 'vietqr' ? 'VietQR' : 'COD' }}</small><small class="items">{{ itemSummary(order) }}</small></div><div><b>{{ money(order.final_amount) }}</b><small :class="order.order_status">{{ label(order.order_status) }}</small><small v-if="activeTab === 'review'" class="review-cta">Đánh giá ngay →</small></div><span>→</span></router-link>
  </section>
</template>
<script setup>
import { ref, computed, onMounted } from 'vue'; import { orderApi } from '../api';
const orders=ref([]),loading=ref(true),activeTab=ref('all');
const tabs=[{id:'all',label:'Tất cả'},{id:'pending',label:'Chờ xác nhận'},{id:'delivery',label:'Chờ giao'},{id:'completed',label:'Đã giao'},{id:'cancelled',label:'Đã hủy'},{id:'review',label:'Đánh giá'}];
const money=v=>Number(v||0).toLocaleString('vi-VN')+'đ';const date=v=>new Date(v).toLocaleDateString('vi-VN');const label=v=>({pending:'Chờ xác nhận',confirmed:'Đã xác nhận',picking:'Đang soạn hàng',shipping:'Đang giao',completed:'Đã giao',cancelled:'Đã hủy',cancellation_requested:'Chờ hủy'})[v]||v;
const matchesTab=(order,tab)=>tab==='all'||(tab==='pending'&&order.order_status==='pending')||(tab==='delivery'&&['confirmed','picking','shipping'].includes(order.order_status))||((tab==='completed'||tab==='review')&&order.order_status==='completed')||(tab==='cancelled'&&['cancelled','cancellation_requested'].includes(order.order_status));
const filteredOrders=computed(()=>orders.value.filter(order=>matchesTab(order,activeTab.value)));const countFor=tab=>orders.value.filter(order=>matchesTab(order,tab)).length;const itemSummary=order=>{const items=order.order_items||[];if(!items.length)return 'Đơn hàng Tiệm Ốc';const first=items[0].products?.name||'Sản phẩm';return items.length>1?`${first} và ${items.length-1} sản phẩm khác`:first;};
onMounted(async()=>{try{orders.value=(await orderApi.getMyOrders({limit:100})).orders||[]}finally{loading.value=false}});
</script>
<style scoped>.history{max-width:900px;padding:3rem 1.25rem 5rem}.history h1{color:var(--color-primary);margin-bottom:.25rem}.history>p{color:var(--color-text-muted)}.order-tabs{display:flex;overflow-x:auto;border-bottom:1px solid var(--border-color);margin:2rem 0 1.25rem}.order-tabs button{flex:0 0 auto;padding:.8rem 1rem;border:0;border-bottom:2px solid transparent;background:none;color:var(--color-text-muted);font:inherit;font-weight:700;cursor:pointer}.order-tabs button.active{color:var(--color-primary);border-bottom-color:var(--color-primary)}.order-tabs span{display:inline-grid;place-items:center;min-width:18px;height:18px;border-radius:9px;background:var(--bg-surface-soft);font-size:.7rem;margin-left:3px}.order{display:flex;align-items:center;justify-content:space-between;gap:1rem;background:#fff;border:1px solid var(--border-color);margin-top:10px;padding:1rem;color:var(--color-text-main)}.order div{display:grid;gap:5px}.order-main{min-width:0}.order div:nth-child(2){text-align:right}.order small{color:var(--color-text-muted)}.items{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:480px}.order .shipping{color:#087ec1}.order .completed{color:#19843a}.order .cancelled,.order .cancellation_requested{color:#b52828}.review-cta{color:var(--color-primary)!important;font-weight:700}.empty{padding:2rem;background:#fff;border:1px solid var(--border-color);text-align:center;color:var(--color-text-muted)}</style>
